/**
 * Helpers around calendar-invite mails.
 *
 * Invite bodies are almost always machine-generated by the sender's
 * groupware and duplicate what the invitation card already shows. We only
 * suppress the formats we positively recognize — an unrecognized body is
 * assumed to be a real, hand-written message and stays visible.
 */

const NAMED_ENTITIES: Record<string, string> = {
  amp: '&',
  lt: '<',
  gt: '>',
  quot: '"',
  apos: "'",
  nbsp: ' ',
};

function decodeEntities(value: string): string {
  return value.replace(/&(#x?[0-9a-f]+|[a-z]+);/gi, (match, entity: string) => {
    if (entity.startsWith('#')) {
      const code =
        entity[1]?.toLowerCase() === 'x'
          ? Number.parseInt(entity.slice(2), 16)
          : Number.parseInt(entity.slice(1), 10);
      return Number.isNaN(code) ? match : String.fromCodePoint(code);
    }
    return NAMED_ENTITIES[entity.toLowerCase()] ?? match;
  });
}

/**
 * Normalize an ICS DESCRIPTION for display as plain text.
 *
 * Organizers' tools store either plain text or HTML fragments in there
 * (Zoom and Thunderbird emit `<br>`/`<p>` soup). Tags are flattened to
 * newlines, entities decoded, and decorative divider lines dropped.
 */
export function icsDescriptionToText(description: string): string {
  let text = description.replace(/\r\n?/g, '\n');
  if (/<[a-z][^>]*>|<\/[a-z]+>/i.test(text)) {
    text = text
      .replace(/<\s*(?:br|\/p|\/div|\/li|\/tr|\/h[1-6])[^>]*>/gi, '\n')
      .replace(/<[^>]+>/g, '');
    text = decodeEntities(text);
  }
  return text
    .split('\n')
    .map((line) => line.trimEnd())
    .filter((line) => !/^[\s─—=_*-]{3,}$/.test(line))
    .join('\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

// Field sheets à la "Item Type:  Appointment" (Exchange, Notes, HCL Verse).
const LABEL_LINE = new RegExp(
  '^(item type|start date|end date|start time|end time|duration|place|location|action' +
    '|organizer|organiser|invitees|required attendees|optional attendees|recurrence' +
    '|chair|subject|when|where|time|date):',
  'i',
);

const GROUP_NOTICE =
  /Termin ist in der Gruppe .+ (angelegt|geändert|aktualisiert|verschoben|gelöscht) worden/;

const BARE_CANCEL = /^(dieser termin wurde abgesagt\.?|this (event|meeting) has been cancell?ed\.?)$/i;

/**
 * True when a mail body is a recognized machine-generated invite rendering
 * that the invitation card fully duplicates. Deliberately conservative:
 * anything we cannot classify is treated as hand-written content.
 */
export function isKnownInviteBoilerplate(bodyText: string): boolean {
  const text = bodyText.replace(/\r\n?/g, '\n').trim();
  if (!text) return false;

  // Google Calendar's generated mails always end in this support-article link.
  if (text.includes('support.google.com/calendar/answer/37135')) return true;

  // DFN/Open-Xchange group-calendar notifications.
  if (GROUP_NOTICE.test(text)) return true;

  const lines = text.split('\n').filter((line) => line.trim().length > 0);

  // A pure field sheet: every line is a label or an indented continuation.
  const labelLines = lines.filter((line) => LABEL_LINE.test(line));
  const continuations = lines.filter((line) => /^\s/.test(line));
  if (labelLines.length >= 3 && labelLines.length + continuations.length === lines.length) {
    return true;
  }

  // Nothing but the cancellation sentence.
  if (lines.length <= 2 && BARE_CANCEL.test(lines.join(' ').trim())) return true;

  return false;
}
